\section{Introduction}

The Lorenz attractor is usually met as a numerical object: one integrates a vector field, plots an orbit, and estimates invariants. The geometric theory of the Lorenz flow, however, offers a different presentation. Strong contraction along the stable foliation collapses the flow onto a branched two-manifold, the \emph{Lorenz template}, whose first-return map is one-dimensional. Coding the branches turns orbits into infinite words and the return map into the shift; admissibility is governed by a finite directed graph. All surviving information is combinatorial.

This paper takes that reduction as a definition and asks what can be proved about the resulting objects \emph{as algebra}. The answer is: essentially everything one wants, with unexpected arithmetic rigidity at the end.

\subsection*{Contributions}
Write $E$ for a directed graph on a finite vertex set $V$ and $A=A(E)$ for its $0/1$ transfer matrix.
\begin{enumerate}
\item \textbf{Inverse-limit theorem} (\S3): $\Lambda_E\cong\varprojlim_n P_n(E)$, canonically and without hypotheses, compatibly with the shift.
\item \textbf{Topology} (\S4): compact, Hausdorff, totally disconnected; Cantor set under branching; $\Lambda\cong\{0,1\}^{\NN}$ for the Lorenz template.
\item \textbf{Counting} (\S5): $n$-periodic points $\leftrightarrow$ closed walks $\leftrightarrow \tr(A^n)$; Cayley--Hamilton recurrence; conjugacy invariance.
\item \textbf{Entropy exists} (\S6): submultiplicativity plus Fekete; $h\le\log|V|$; monotonicity.
\item \textbf{Spectral form} (\S7): $h=\log\lambda$; uniqueness of $\lambda$; $1\le\lambda\le|V|$; $e^h$ an algebraic integer.
\item \textbf{Existence} (\S8): Collatz--Wielandt for primitive graphs; simplicity; dominance; $h>0$.
\item \textbf{Periodic growth} (\S9): $n^{-1}\log\tr(A^n)\to h$; conjugacy invariance of $h$ and $\lambda$.
\item \textbf{Chaos} (\S10) and \textbf{the two templates} (\S11).
\end{enumerate}

\section{Definitions}

Throughout $V$ is a finite nonempty set and $E\subseteq V\times V$ a directed-graph edge relation; we write $u\to v$ for $(u,v)\in E$.

\begin{definition}[Finite path sets]
For $n\in\NN$, $P_n(E)=\{w:\{0,\dots,n\}\to V \mid w_i\to w_{i+1}\ \forall i<n\}$, the walks using exactly $n$ edges. Each $P_n(E)$ is finite and $|P_0(E)|=|V|$.
\end{definition}

\begin{definition}[Bonding maps]
$\pi_n:P_{n+1}(E)\to P_n(E)$ restricts a walk to its first $n$ edges (\emph{edge deletion}).
\end{definition}

\begin{definition}[Orbit space]
$\Lambda_E=\{x:\NN\to V \mid x_n\to x_{n+1}\ \forall n\}\subseteq V^{\NN}$, with the subspace topology from the product of discrete copies of $V$. The \emph{shift} is $\sigma(x)_n=x_{n+1}$.
\end{definition}

\begin{definition}[Inverse limit]
$\varprojlim_n P_n(E)=\bigl\{(f_n)\in\prod_n P_n(E)\ \big|\ \pi_n(f_{n+1})=f_n\ \forall n\bigr\}$.
\end{definition}

\begin{definition}[Transfer matrix]
$A=A(E)\in\ZZ^{V\times V}$ with $A_{ij}=1$ if $i\to j$ and $0$ otherwise.
\end{definition}

\begin{definition}[Structural hypotheses]
$E$ has \emph{no dead ends} if every vertex has out-degree $\ge1$; is \emph{branching} if every out-degree is $\ge2$; is \emph{primitive} if there is $N\ge1$ such that for every $n\ge N$ and every ordered pair $(u,v)$ there is a walk of length exactly $n$ from $u$ to $v$.
\end{definition}

\begin{definition}
$\CW_n(E)=\{w\in P_n(E): w_0=w_n\}$ and $\Per_n(E)=\{x\in\Lambda_E: \sigma^n(x)=x\}$. Graphs $E,F$ are \emph{conjugate} if there is a shift-equivariant bijection $\Lambda_E\to\Lambda_F$.
\end{definition}

\begin{definition}[Perron datum]
A \emph{Perron datum} for $E$ is a pair $(\lambda,v)$ with $v:V\to\RR$ strictly positive in every coordinate and $\sum_j A_{ij}v_j=\lambda v_i$ for all $i$, i.e.\ $Av=\lambda v$ with $v>0$. We call $\lambda$ the \emph{Perron value}.
\end{definition}

\begin{definition}[Entropy]
For dead-end-free $E$ put $L_n=\log|P_n(E)|$ and $h(E)=\lim_{n\to\infty}L_n/n$ (existence: Theorem~\ref{thm:entropy-exists}).
\end{definition}

\begin{definition}[The two templates]
$V=\{\mathsf L,\mathsf R\}$. The \emph{Lorenz template} $E_\Lor$ allows all four transitions, $A_\Lor=\left(\begin{smallmatrix}1&1\\1&1\end{smallmatrix}\right)$. The \emph{pruned template} $E_\pr$ forbids $\mathsf R\to\mathsf R$, $A_\pr=\left(\begin{smallmatrix}1&1\\1&0\end{smallmatrix}\right)$.
\end{definition}

\section{The inverse-limit theorem}

\begin{theorem}[Inverse Limit Theorem]\label{thm:invlim}
For every finite directed graph $E$ the map $\Phi(x)_n=(x_0,\dots,x_n)$ is a canonical bijection $\Lambda_E\xrightarrow{\ \sim\ }\varprojlim_n P_n(E)$.
\end{theorem}

\begin{proof}[Proof sketch]
$\Phi(x)_n$ is a walk and $\pi_n(\Phi(x)_{n+1})=\Phi(x)_n$, so $\Phi$ lands in the limit. Conversely, coherence of $(f_n)$ says $f_{n+1}$ restricted to $\{0,\dots,n\}$ is $f_n$; hence $x_n:=(f_n)_n$ is well defined and $(f_m)_k=x_k$ for all $k\le m$ by induction on $m-k$. The edge condition $x_n\to x_{n+1}$ is the last edge condition of $f_{n+1}$. The constructions are mutually inverse by extensionality.
\end{proof}

\begin{theorem}
$\Phi$ intertwines $\sigma$ with the map deleting the first edge at every level: $\Phi(\sigma x)_n=(x_1,\dots,x_{n+1})$.
\end{theorem}

\begin{theorem}[Nondegeneracy]
If $E$ has no dead ends, every $\pi_n$ is surjective and $P_n(E)\neq\emptyset$; consequently $\Lambda_E\neq\emptyset$.
\end{theorem}

\begin{proof}[Proof sketch]
Append an out-neighbour of the last vertex; iterate from any vertex for nonemptiness.
\end{proof}

\section{Topology of the limit}

\begin{theorem}[Compactness]
$\Lambda_E$ is closed in $V^\NN$, hence compact, Hausdorff and totally disconnected.
\end{theorem}

\begin{proof}[Proof sketch]
$\Lambda_E=\bigcap_n\{x: (x_n,x_{n+1})\in E\}$, an intersection of preimages of clopen sets under continuous evaluations. Closed subspaces inherit the three properties.
\end{proof}

\begin{theorem}
$\sigma:\Lambda_E\to\Lambda_E$ is continuous, so $(\Lambda_E,\sigma)$ is a topological dynamical system.
\end{theorem}

\begin{theorem}[Embedded Cantor set]
If $E$ is branching then for each $v_0\in V$ there is a closed topological embedding $\{0,1\}^\NN\hookrightarrow\Lambda_E$. Consequently $\Lambda_E$ is uncountable.
\end{theorem}

\begin{proof}[Proof sketch]
Branching gives, for each $v$, distinct out-neighbours $s_0(v)\neq s_1(v)$. Set $c(b)_0=v_0$, $c(b)_{n+1}=s_{b_n}(c(b)_n)$. This is an orbit, injective (compare at the first differing index), continuous (each coordinate depends on finitely many $b_i$), hence a closed embedding by compactness.
\end{proof}

\begin{theorem}[Perfectness]
If $E$ is branching, $\Lambda_E$ has no isolated points; being compact, metrizable and totally disconnected, it is a Cantor set.
\end{theorem}

\begin{proof}[Proof sketch]
Given $x$ and $n$, branch at step $n$ to an out-neighbour different from $x_{n+1}$ and continue; cylinders form a neighbourhood basis.
\end{proof}

\begin{theorem}
$\Lambda_{E_\Lor}\cong\{0,1\}^\NN$, by the map forgetting the (vacuous) edge conditions.
\end{theorem}

\section{Counting: closed walks, traces, rationality}

\begin{theorem}[Periodic points are closed walks]\label{thm:per}
For $n\ge1$ there is a canonical bijection $\Per_n(E)\cong\CW_n(E)$.
\end{theorem}

\begin{proof}[Proof sketch]
$\sigma^n x=x$ means $x_{k+n}=x_k$ for all $k$, so $x$ is determined by $x_0,\dots,x_{n-1}$ and $(x_0,\dots,x_n)$ is a closed walk. Conversely a closed walk extends periodically; the wrap-around edge condition holds because $w_n=w_0$. The maps are inverse via reduction modulo $n$.
\end{proof}

\begin{theorem}[Matrix counting]\label{thm:count}
$(A^n)_{ij}$ is the number of $n$-edge walks from $i$ to $j$; hence $|P_n(E)|=\sum_{i,j}(A^n)_{ij}$ and $|\CW_n(E)|=\tr(A^n)$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $n$, classifying walks by their penultimate vertex; this is exactly the matrix product.
\end{proof}

\begin{theorem}
If $E$ and $F$ are conjugate then $\tr(A(E)^n)=\tr(A(F)^n)$ for all $n\ge1$.
\end{theorem}

\begin{theorem}[Cayley--Hamilton recurrence]\label{thm:ch}
Let $M$ be $d\times d$ over a commutative ring, $\chi_M(t)=\sum_{i=0}^d c_it^i$ with $c_d=1$. Then $\sum_{i=0}^d c_i\tr(M^{k+i})=0$ for all $k\ge0$.
\end{theorem}

\begin{proof}[Proof sketch]
Multiply $\chi_M(M)=0$ by $M^k$, expand, and take traces, using linearity of the trace.
\end{proof}

\begin{corollary}[Rationality, finite-graph form]
$n\mapsto|\Per_n(E)|$ satisfies an integer linear recurrence of order at most $|V|$ with coefficients those of $\chi_A$; equivalently, its generating function is rational.
\end{corollary}

\begin{example}
For $2\times2$ matrices, $\tr(M^{k+2})=(\tr M)\tr(M^{k+1})-(\det M)\tr(M^k)$. For $A_\Lor$ ($\tr=2$, $\det=0$) this gives $\tr(A^n)=2^n$; for $A_\pr$ ($\tr=1$, $\det=-1$) the Lucas numbers $1,3,4,7,11,18,\dots$.
\end{example}

\begin{corollary}[Non-conjugacy]
$E_\Lor$ and $E_\pr$ are not topologically conjugate, since $\tr(A_\Lor^2)=4\neq3=\tr(A_\pr^2)$.
\end{corollary}

\section{Entropy exists}

\begin{lemma}[Submultiplicativity]
$|P_{m+n}(E)|\le|P_m(E)|\cdot|P_n(E)|$.
\end{lemma}

\begin{proof}[Proof sketch]
Sending a walk of length $m+n$ to its first $m$ and last $n$ edges is injective: the halves overlap at index $m$ and jointly determine all coordinates.
\end{proof}

\begin{theorem}[Existence of entropy]\label{thm:entropy-exists}
For dead-end-free $E$, $L_n=\log|P_n(E)|$ is nonnegative and subadditive, so by Fekete's lemma $h(E)=\lim_n L_n/n=\inf_{n\ge1}L_n/n$ exists and is finite.
\end{theorem}

\begin{theorem}
$0\le h(E)\le\log|V|$; and $E\subseteq F$ (both dead-end-free) implies $h(E)\le h(F)$.
\end{theorem}

\section{The spectral form of the entropy}

Fix a Perron datum $(\lambda,v)$ for $E$.

\begin{lemma}[Propagation to powers]\label{lem:pow}
For all $n$ and $i$, $\sum_j (A^n)_{ij}v_j=\lambda^n v_i$.
\end{lemma}

\begin{proof}[Proof sketch]
Induction on $n$: expand $(A^{n+1})_{ij}=\sum_k(A^n)_{ik}A_{kj}$, exchange summation order, apply the eigenvector equation at $k$, and factor out $\lambda$.
\end{proof}

\begin{lemma}
If $E$ has no dead ends then $\lambda>0$.
\end{lemma}

\begin{proof}[Proof sketch]
For any $i$ with out-neighbour $j_0$, $\lambda v_i=\sum_j A_{ij}v_j\ge v_{j_0}>0$ and $v_i>0$.
\end{proof}

\begin{lemma}[Counting bounds]\label{lem:bounds}
Let $c=\min_i v_i$, $C=\max_i v_i$, $S=\sum_i v_i$. Then for all $n$,
\[ \frac{S}{C}\lambda^n \ \le\ |P_n(E)| \ \le\ \frac{S}{c}\lambda^n. \]
\end{lemma}

\begin{proof}[Proof sketch]
Summing Lemma~\ref{lem:pow} over $i$ gives $\sum_{i,j}(A^n)_{ij}v_j=\lambda^nS$. Bounding $v_j$ between $c$ and $C$ inside the double sum and using $|P_n(E)|=\sum_{i,j}(A^n)_{ij}$ gives $c|P_n(E)|\le\lambda^nS\le C|P_n(E)|$.
\end{proof}

\begin{theorem}[Spectral Entropy Theorem]\label{thm:spectral}
Let $E$ be a finite directed graph without dead ends carrying a Perron datum $(\lambda,v)$. Then
\[ h(E)=\log\lambda. \]
\end{theorem}

\begin{proof}[Proof sketch]
Taking logarithms in Lemma~\ref{lem:bounds}, $\log(S/C)+n\log\lambda\le L_n\le\log(S/c)+n\log\lambda$. Divide by $n$: both bounds have the form $a/n+\log\lambda\to\log\lambda$, so $L_n/n\to\log\lambda$ by squeezing. Since $L_n/n\to h(E)$ and limits are unique, $h(E)=\log\lambda$.
\end{proof}

\begin{remark}
Only the minimum and maximum coordinates of $v$ enter, and both are washed out by dividing by $n$. No irreducibility, aperiodicity or spectral gap is required --- only positivity.
\end{remark}

\begin{theorem}[Uniqueness of the Perron value]\label{thm:unique}
For dead-end-free $E$, any two Perron data have the same value. This is the uniqueness half of Perron--Frobenius, obtained by a purely dynamical route.
\end{theorem}

\begin{proof}[Proof sketch]
Both values are positive and both logarithms equal $h(E)$ by Theorem~\ref{thm:spectral}; $\log$ is injective on $(0,\infty)$.
\end{proof}

\begin{corollary}
$1\le\lambda\le|V|$.
\end{corollary}

\begin{proof}[Proof sketch]
Upper: $\log\lambda=h(E)\le\log|V|$. Lower: at a coordinate $i_0$ minimising $v$, $\lambda v_{i_0}=\sum_jA_{i_0j}v_j\ge v_{j_0}\ge v_{i_0}$ for an out-neighbour $j_0$.
\end{proof}

\subsection{Arithmetic rigidity}

\begin{lemma}
If $(\lambda,v)$ is a Perron datum then $\det(\lambda I-A)=0$ over $\RR$.
\end{lemma}

\begin{theorem}[Arithmeticity of the Perron value]\label{thm:alg}
$\lambda$ is an algebraic integer: a root of the monic characteristic polynomial $\chi_A\in\ZZ[t]$ of the integral transfer matrix.
\end{theorem}

\begin{proof}[Proof sketch]
$\chi_A$ is monic with integer coefficients since $A$ is integral; its image in $\RR[t]$ is the characteristic polynomial of the real transfer matrix, whose value at $\lambda$ is $\det(\lambda I-A)=0$.
\end{proof}

\begin{corollary}[Arithmeticity of the entropy]
For every symbolic attractor admitting a Perron datum, $e^{h(E)}$ is an algebraic integer; hence $h(E)$ lies in the countable set $\{\log\alpha:\alpha>0\text{ an algebraic integer}\}$.
\end{corollary}

\section{Existence of Perron data}

Let $E$ be primitive and $A$ its real transfer matrix.

\begin{lemma}[Primitivity is matrix positivity]\label{lem:prim}
$E$ is primitive if and only if there is $N\ge1$ with $(A^n)_{uv}\ge1$ for all $n\ge N$ and all $u,v$.
\end{lemma}

Thus the hypothesis behind mixing and the hypothesis of Perron--Frobenius are the same condition. In particular primitive graphs are dead-end-free.

\begin{definition}[Collatz--Wielandt set]
$\mathcal C=\{(t,x)\in\RR\times\RR^V : x\in\Delta,\ tx_i\le(Ax)_i\ \forall i\}$, where $\Delta$ is the standard simplex.
\end{definition}

\begin{lemma}
$\mathcal C$ is compact and nonempty, and $(t,x)\in\mathcal C$ forces $0\le t\le|V|$.
\end{lemma}

\begin{proof}[Proof sketch]
Closedness from continuity of $x\mapsto Ax$; boundedness by summing $tx_i\le(Ax)_i$ over $i$, giving $t\le|V|$; nonemptiness since the uniform vector works for $t=1$ when there are no dead ends.
\end{proof}

\begin{theorem}[A maximiser is an eigenvector]
Let $r=\max\{t:(t,x)\in\mathcal C\}$, attained at $(r,x)$. Then $Ax=rx$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $w=Ax-rx\ge0$ and suppose $w\neq0$. Choose $k$ with $A^k>0$ entrywise, so $A^kw>0$. Put $y=A^kx/\|A^kx\|_1\in\Delta$; then $Ay-ry=A^kw/\|A^kx\|_1>0$ strictly, so $Ay\ge(r+\varepsilon)y$ for some $\varepsilon>0$ by finiteness, contradicting maximality.
\end{proof}

\begin{theorem}[Existence]
Every primitive finite directed graph carries a Perron datum, and (by Theorem~\ref{thm:unique}) its value $\lambda_{\mathrm P}(E)$ is unique.
\end{theorem}

\begin{proof}[Proof sketch]
The maximiser $x\in\Delta$ is nonnegative and nonzero, and $r^kx=A^kx>0$ with $r\ge1$, so $x>0$.
\end{proof}

\begin{theorem}[Unconditional spectral entropy]
For every primitive finite directed graph, $h(E)=\log\lambda_{\mathrm P}(E)$, $e^{h(E)}=\lambda_{\mathrm P}(E)$ is an algebraic integer, and $1\le\lambda_{\mathrm P}(E)\le|V|$.
\end{theorem}

\begin{theorem}[Positive entropy]
If $E$ is primitive with $|V|\ge2$ then $\lambda_{\mathrm P}(E)>1$ and $h(E)>0$.
\end{theorem}

\begin{theorem}[Geometric simplicity]
For primitive $E$, the $\lambda_{\mathrm P}$-eigenspace is the line spanned by the positive eigenvector.
\end{theorem}

\begin{proof}[Proof sketch]
For an eigenvector $y$ and the positive $v$, put $t=\min_i y_i/v_i$, attained at $i_0$. Then $y-tv$ is a nonnegative eigenvector with a zero coordinate; applying a positive power of $A$ would make it strictly positive unless it vanishes, and its $i_0$ coordinate stays zero, so $y=tv$.
\end{proof}

\begin{theorem}[Spectral dominance]
For primitive $E$, every real eigenvalue $\mu$ of $A$ satisfies $|\mu|\le\lambda_{\mathrm P}(E)$; hence the entropy is the logarithm of the spectral radius.
\end{theorem}

\begin{proof}[Proof sketch]
Take $i_0$ maximising $|y_i|/v_i$; then $|\mu||y_{i_0}|\le\sum_jA_{i_0j}|y_j|\le(|y_{i_0}|/v_{i_0})\sum_jA_{i_0j}v_j=\lambda_{\mathrm P}|y_{i_0}|$.
\end{proof}

\section{Periodic orbits grow at the entropy rate}

\begin{lemma}[Upper bound]\label{lem:up}
For any Perron datum, $(A^n)_{ii}\le\lambda^n$ for all $i$, hence $\tr(A^n)\le|V|\lambda^n$.
\end{lemma}

\begin{lemma}[Lower bound via primitivity]\label{lem:low}
If all entries of $A^m$ are $\ge1$ then $(A^q)_{jk}\le(A^{m+q+m})_{ii}$ for all $i,j,k$, and consequently $|P_q(E)|\le|V|^2\,|\CW_{q+2m}(E)|$.
\end{lemma}

\begin{proof}[Proof sketch]
Prefix a walk $i\to j$ of length $m$ and suffix a walk $k\to i$ of length $m$; sum over the at most $|V|^2$ pairs $(j,k)$ and bound $\tr(A^{q+2m})\ge(A^{q+2m})_{ii}$.
\end{proof}

\begin{theorem}[Periodic Growth Theorem]
For primitive $E$ with Perron value $\lambda$,
\[ \lim_{n\to\infty}\frac{\log|\CW_n(E)|}{n}=\log\lambda=h(E). \]
\end{theorem}

\begin{proof}[Proof sketch]
The upper bound is Lemma~\ref{lem:up}. For the lower bound, write $n=m+q+m$; Lemma~\ref{lem:low} and $|P_q|\ge(S/C)\lambda^q$ give $|\CW_n|\ge a'\lambda^n$ with $a'=(S/C)/(|V|^2\lambda^{2m})>0$. Take logarithms, divide by $n$, and squeeze.
\end{proof}

\begin{corollary}
Entropy and the Perron value are topological conjugacy invariants for primitive attractors, since conjugate systems have equal closed-walk counts.
\end{corollary}

\section{Chaos from primitivity}

\begin{theorem}[Topological mixing]
If $E$ is primitive then for all nonempty open $U,U'\subseteq\Lambda_E$ there is $N$ with $\sigma^n(U)\cap U'\neq\emptyset$ for all $n\ge N$.
\end{theorem}

\begin{proof}[Proof sketch]
Shrink to cylinders of depths $m,m'$ around points $x,x'$; primitivity gives, for all large $n$, a walk of length exactly $n-m$ from $x_m$ to $x'_0$; concatenate and continue.
\end{proof}

\begin{theorem}[Dense periodic orbits]
If $E$ is primitive, periodic points are dense in $\Lambda_E$.
\end{theorem}

\begin{theorem}[Converse]
A dead-end-free graph whose attractor is topologically mixing is primitive. Hence for dead-end-free graphs, primitivity $\Leftrightarrow$ topological mixing.
\end{theorem}

\begin{corollary}[Devaney chaos]
A primitive branching symbolic attractor is chaotic in Devaney's sense: mixing, with dense periodic orbits and sensitive dependence on initial conditions. Both Lorenz templates qualify.
\end{corollary}

